#!/usr/bin/env python3
"""
Money flow topology classifier and anti-pattern detector.

6 topology patterns (legal money architectures):
1. Circular flow (premium → float → invest → acquire → premium)
2. Multi-hop relabeling (value relabeled at each hop for different treatment)
3. Trust arbitrage (borrow established entity's trust for access)
4. Entity multiplication (1 activity → N entities → N revenue streams)
5. Float capture (collect early, pay late, invest the gap)
6. Liability routing (isolate risk/liability per entity per jurisdiction)

Usage:
    python -m money_mechanisms.flow_topology --description "marketplace with 14-day seller payment hold"
"""

import argparse
import json
import re
import sys
from typing import Dict, List, Optional, Tuple


class FlowTopologyAnalyzer:
    """Classifier for money flow topology patterns."""

    TOPOLOGY_PATTERNS = {
        "circular_flow": {
            "description": "Revenue reinvested to generate more of the same revenue type",
            "keywords": [
                "franchise", "royalty", "recurring", "reinvest", "premium",
                "subscription", "float", "compound", "flywheel", "loop"
            ],
            "example": "Berkshire: premium → float → invest → acquire → more premium",
            "leverage_multiplier": 3.0
        },
        "multi_hop_relabeling": {
            "description": "Value passes through entities, relabeled at each hop",
            "keywords": [
                "platform", "processing_fee", "service_fee", "markup",
                "referral", "commission", "interchange", "rebate", "reseller"
            ],
            "example": "Payment processor: purchase → interchange → processing fee → net settlement",
            "leverage_multiplier": 2.0
        },
        "trust_arbitrage": {
            "description": "Borrow established entity's trust to access otherwise closed markets",
            "keywords": [
                "marketplace", "payment_processor", "verified", "accredited",
                "licensed", "certified", "compliance", "white_label", "payfac",
                "api", "wrapper", "aggregator"
            ],
            "example": "Stripe: borrows Visa/bank trust → relends to millions of merchants",
            "leverage_multiplier": 3.5
        },
        "entity_multiplication": {
            "description": "One activity generates N revenue streams via separate entities",
            "keywords": [
                "holding", "subsidiary", "franchise", "multi_entity", "spv",
                "licensing", "real_estate", "management_fee", "brand_license",
                "separate_p_and_l"
            ],
            "example": "McDonald's: franchise royalty + rent + supply chain = 3 P&Ls per restaurant",
            "leverage_multiplier": 2.5
        },
        "float_capture": {
            "description": "Collect payment before obligation, invest the time gap",
            "keywords": [
                "prepaid", "deposit", "escrow", "insurance", "marketplace_payout",
                "annual_plan", "advance", "retainer", "security_deposit",
                "payment_hold", "settlement_delay"
            ],
            "example": "Amazon: customer pays Day 0, seller paid Day 14 = 14-day investable float",
            "leverage_multiplier": 2.0
        },
        "liability_routing": {
            "description": "Isolate specific risks/liabilities in purpose-built entities",
            "keywords": [
                "spv", "llc_per", "limited_liability", "project_entity",
                "non_recourse", "ring_fence", "subsidiary", "ip_holding",
                "operating_entity", "asset_protection"
            ],
            "example": "WeWork SPV: 1 LLC per building, failure isolated to that entity",
            "leverage_multiplier": 1.5
        }
    }

    ANTI_PATTERNS = {
        "circular_fraud": {
            "description": "Fake transactions cycling between controlled entities to inflate revenue",
            "red_flags": ["round_trip", "self_dealing", "wash_trading", "inflated_volume"],
            "legal_risk": "Securities fraud, wire fraud, tax evasion"
        },
        "shell_layering": {
            "description": "Entities exist solely to obscure beneficial ownership or source of funds",
            "red_flags": ["no_substance", "nominee_directors", "bearer_shares", "layered_ownership"],
            "legal_risk": "Money laundering, sanctions evasion, BSA violations"
        },
        "trust_abuse": {
            "description": "Exploiting borrowed trust to facilitate fraud against end users",
            "red_flags": ["fake_reviews", "credential_fraud", "identity_theft", "unauthorized_charges"],
            "legal_risk": "Wire fraud, identity theft, FTC enforcement"
        },
        "float_theft": {
            "description": "Intentionally delaying payments beyond contractual terms to capture unauthorized float",
            "red_flags": ["extended_holds", "unreasonable_delays", "commingled_funds", "missing_escrow"],
            "legal_risk": "Breach of fiduciary duty, money transmitter violations"
        }
    }

    @classmethod
    def classify_topology(cls, description: str) -> List[Dict]:
        """Classify money flow topology patterns in a business description."""
        desc_lower = description.lower().replace("-", "_").replace(" ", "_")
        desc_words = set(re.findall(r'[a-z_]+', desc_lower))

        matches = []
        for pattern_name, pattern in cls.TOPOLOGY_PATTERNS.items():
            keyword_hits = [kw for kw in pattern["keywords"] if kw in desc_lower or kw in desc_words]
            if keyword_hits:
                confidence = min(len(keyword_hits) / 3.0, 1.0)
                matches.append({
                    "pattern": pattern_name,
                    "confidence": round(confidence, 2),
                    "keywords_matched": keyword_hits,
                    "description": pattern["description"],
                    "leverage_multiplier": pattern["leverage_multiplier"]
                })

        matches.sort(key=lambda x: x["confidence"], reverse=True)
        return matches

    @classmethod
    def calculate_topology_score(cls, patterns: List[Dict]) -> Dict:
        """Calculate composite topology score from matched patterns."""
        if not patterns:
            return {"score": 1, "interpretation": "linear", "detail": "No topology patterns detected"}

        top = patterns[0]
        base = min(top["confidence"] * 7 + 2, 9.0)
        bonus = min(len(patterns) - 1, 3) * 0.5
        score = round(min(base + bonus, 10.0), 1)

        if score >= 7:
            interp = "multi_entity_compound"
        elif score >= 4:
            interp = "structured_advantage"
        else:
            interp = "simple_structure"

        return {
            "score": score,
            "interpretation": interp,
            "primary_pattern": top["pattern"],
            "pattern_count": len(patterns),
            "leverage_multiplier": top["leverage_multiplier"],
            "patterns": [p["pattern"] for p in patterns]
        }

    @classmethod
    def detect_anti_patterns(cls, description: str) -> List[Dict]:
        """Flag potential fraud indicators (advisory output only)."""
        desc_lower = description.lower().replace("-", "_").replace(" ", "_")
        flags = []
        for name, ap in cls.ANTI_PATTERNS.items():
            hits = [rf for rf in ap["red_flags"] if rf in desc_lower]
            if hits:
                flags.append({
                    "anti_pattern": name,
                    "red_flags_matched": hits,
                    "description": ap["description"],
                    "legal_risk": ap["legal_risk"],
                    "advisory_only": True
                })
        return flags

    @classmethod
    def full_analysis(cls, description: str) -> Dict:
        """Complete topology analysis."""
        patterns = cls.classify_topology(description)
        score = cls.calculate_topology_score(patterns)
        anti = cls.detect_anti_patterns(description)
        return {
            "topology_patterns": patterns,
            "topology_score": score,
            "anti_patterns": anti,
            "disclaimer": "Structural analysis is pattern recognition, not legal/financial advice"
        }


def main():
    parser = argparse.ArgumentParser(description="Flow Topology Analyzer")
    parser.add_argument("--description", type=str, required=True, help="Business description to analyze")
    parser.add_argument("--output", choices=["json", "text"], default="json")
    args = parser.parse_args()

    result = FlowTopologyAnalyzer.full_analysis(args.description)

    if args.output == "json":
        print(json.dumps(result, indent=2))
    else:
        s = result["topology_score"]
        print(f"Topology Score: {s['score']}/10 ({s['interpretation']})")
        if result["topology_patterns"]:
            print(f"Primary: {s['primary_pattern']} ({result['topology_patterns'][0]['confidence']:.0%} confidence)")
        if result["anti_patterns"]:
            print(f"WARNING: {len(result['anti_patterns'])} anti-pattern(s) flagged")
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""
Structural leverage scorer — 5 architectural leverage types beyond Naval's 4 operational types.

Naval's leverage.py: code, media, capital, labor (operational — HOW you produce)
This module: entity, trust, info_asymmetry, timing, regulatory (structural — HOW you architect)

Usage:
    python -m money_mechanisms.structural_leverage --description "franchise model with IP licensing and real estate"
"""

import argparse
import json
import re
import sys
from typing import Dict, List, Tuple


class StructuralLeverageScorer:
    """Scorer for architectural leverage types."""

    STRUCTURAL_TYPES = {
        "entity_leverage": {
            "description": "1 person/activity → N entities → N× credit/access/revenue",
            "multiplier_range": "2-10x",
            "keywords": [
                "holding_company", "subsidiary", "franchise", "spv", "multi_entity",
                "separate_llc", "brand_license", "management_company", "fund_structure"
            ],
            "weight": 2.0
        },
        "trust_leverage": {
            "description": "Borrow established entity's reputation for higher conversion/access",
            "multiplier_range": "3-5x conversion",
            "keywords": [
                "white_label", "reseller", "authorized", "certified", "marketplace",
                "verified", "payfac", "aggregator", "api_wrapper", "partner_program"
            ],
            "weight": 2.5
        },
        "info_asymmetry": {
            "description": "Know what 2+ parties don't know about each other",
            "multiplier_range": "15-30% deal value",
            "keywords": [
                "broker", "matchmaker", "arbitrage", "insider_knowledge",
                "price_discovery", "market_maker", "intermediary", "sourcing_agent",
                "deal_flow", "information_advantage"
            ],
            "weight": 2.0
        },
        "timing_leverage": {
            "description": "Collect early, pay late = negative working capital / free float",
            "multiplier_range": "free capital at scale",
            "keywords": [
                "prepaid", "annual_plan", "deposit", "retainer", "insurance",
                "escrow", "payment_hold", "net_30", "net_60", "float",
                "advance_payment", "subscription_annual"
            ],
            "weight": 1.5
        },
        "regulatory_leverage": {
            "description": "Compliant where others can't/won't be — monopoly-tier margins",
            "multiplier_range": "monopoly margins in segment",
            "keywords": [
                "licensed", "regulated", "compliance", "accredited", "permit",
                "certificate", "fda_approved", "fintech_charter", "import_license",
                "export_license", "professional_license"
            ],
            "weight": 3.0
        }
    }

    UPGRADE_PATHS = {
        ("single_entity", "entity_leverage"): {
            "steps": ["Register holding company", "Create operating subsidiary", "Separate IP into IP-holding entity"],
            "timeline_months": 3,
            "cost_range": "$2K-$10K",
            "prerequisites": ["Revenue > $50K/year", "Multiple revenue streams or locations"]
        },
        ("direct_sales", "trust_leverage"): {
            "steps": ["Identify trust-holder in your market", "Negotiate reseller/partner agreement", "Integrate their brand/compliance into your offer"],
            "timeline_months": 6,
            "cost_range": "$1K-$5K",
            "prerequisites": ["Complementary offering to trust-holder", "Sales volume to justify partnership"]
        },
        ("single_market", "info_asymmetry"): {
            "steps": ["Map both sides of a market", "Build proprietary deal flow", "Position as connector/broker"],
            "timeline_months": 6,
            "cost_range": "$500-$3K",
            "prerequisites": ["Access to 2+ disconnected market sides", "Domain expertise in pricing"]
        },
        ("invoice_on_delivery", "timing_leverage"): {
            "steps": ["Introduce prepaid/annual pricing", "Negotiate extended payment terms with suppliers", "Build escrow or payment hold into contracts"],
            "timeline_months": 2,
            "cost_range": "$0-$1K",
            "prerequisites": ["Established customer trust", "Predictable delivery timeline"]
        },
        ("unregulated", "regulatory_leverage"): {
            "steps": ["Identify regulation barrier in adjacent market", "Obtain required license/certification", "Enter market where unlicensed competitors cannot"],
            "timeline_months": 12,
            "cost_range": "$5K-$50K",
            "prerequisites": ["Capital for licensing process", "Willingness to handle compliance burden"]
        }
    }

    @classmethod
    def classify_structural_leverage(cls, description: str) -> List[Tuple[str, float]]:
        """Classify structural leverage types in a description."""
        desc_lower = description.lower().replace("-", "_").replace(" ", "_")
        desc_words = set(re.findall(r'[a-z_]+', desc_lower))

        results = []
        for stype, config in cls.STRUCTURAL_TYPES.items():
            hits = [kw for kw in config["keywords"] if kw in desc_lower or kw in desc_words]
            if hits:
                confidence = min(len(hits) / 3.0, 1.0)
                results.append((stype, round(confidence, 2)))

        results.sort(key=lambda x: x[1], reverse=True)
        return results

    @classmethod
    def calculate_structural_score(cls, sources: List[Dict]) -> Dict:
        """Calculate weighted structural leverage score."""
        if not sources:
            return {"score": 1, "interpretation": "no_structural_leverage", "types": []}

        total_weight = 0
        weighted_sum = 0
        type_details = []

        for src in sources:
            stype = src.get("type", "")
            confidence = src.get("confidence", 0.5)
            config = cls.STRUCTURAL_TYPES.get(stype, {})
            weight = config.get("weight", 1.0)

            type_score = confidence * weight * 3.3
            weighted_sum += type_score
            total_weight += weight

            type_details.append({
                "type": stype,
                "confidence": confidence,
                "weight": weight,
                "contribution": round(type_score, 2),
                "multiplier_range": config.get("multiplier_range", "unknown")
            })

        raw = weighted_sum / max(total_weight, 1)
        score = round(min(max(raw + 1, 1), 10), 1)

        if score >= 7:
            interp = "high_structural_leverage"
        elif score >= 4:
            interp = "moderate_structural_leverage"
        else:
            interp = "low_structural_leverage"

        return {
            "score": score,
            "interpretation": interp,
            "type_count": len(sources),
            "types": type_details
        }

    @classmethod
    def design_upgrade_path(cls, current_structure: str, target: str) -> Dict:
        """Design steps to upgrade structural leverage."""
        key = (current_structure, target)
        if key in cls.UPGRADE_PATHS:
            path = cls.UPGRADE_PATHS[key]
            return {"from": current_structure, "to": target, "feasible": True, **path}

        return {
            "from": current_structure, "to": target, "feasible": False,
            "note": f"No predefined path from '{current_structure}' to '{target}'. Consider intermediate steps."
        }

    @classmethod
    def full_analysis(cls, description: str) -> Dict:
        """Complete structural leverage analysis."""
        classified = cls.classify_structural_leverage(description)
        sources = [{"type": t, "confidence": c} for t, c in classified]
        score = cls.calculate_structural_score(sources)

        upgrades = []
        if classified:
            primary = classified[0][0]
            all_types = set(cls.STRUCTURAL_TYPES.keys())
            missing = all_types - {t for t, _ in classified}
            for target in list(missing)[:2]:
                for start_key, path in cls.UPGRADE_PATHS.items():
                    if start_key[1] == target:
                        upgrades.append({"target": target, **path})
                        break

        return {
            "structural_leverage_types": classified,
            "structural_score": score,
            "upgrade_opportunities": upgrades
        }


def main():
    parser = argparse.ArgumentParser(description="Structural Leverage Scorer")
    parser.add_argument("--description", type=str, default=None, help="Business description")
    parser.add_argument("--sources", type=str, default=None, help="JSON array of sources")
    parser.add_argument("--output", choices=["json", "text"], default="json")
    args = parser.parse_args()

    if args.description:
        result = StructuralLeverageScorer.full_analysis(args.description)
    elif args.sources:
        sources = json.loads(args.sources)
        result = StructuralLeverageScorer.calculate_structural_score(sources)
    else:
        parser.error("Either --description or --sources required")
        return 1

    if args.output == "json":
        print(json.dumps(result, indent=2))
    else:
        s = result.get("structural_score", result)
        print(f"Structural Score: {s['score']}/10 ({s['interpretation']})")
        for t in s.get("types", []):
            print(f"  {t['type']}: {t['confidence']:.0%} (weight {t['weight']})")
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""
Value chain position scorer and exit-first design evaluator.

6 position dimensions:
1. Control over demand (do you own the customer relationship?)
2. Information advantage (do you know something others don't?)
3. Switching cost created (how hard to replace you?)
4. Replaceability (inverted — how easily can someone else do this?)
5. Risk bearing (are you bearing risk others won't?)
6. Trust position (are you the trust anchor in the chain?)

Usage:
    python -m money_mechanisms.position_intelligence --description "B2B marketplace connecting VN manufacturers with US buyers"
"""

import argparse
import json
import re
import sys
from typing import Dict, List, Optional


class PositionIntelligence:
    """Value chain position scorer and exit-first designer."""

    POSITION_DIMENSIONS = {
        "control_over_demand": {
            "description": "Do you own the customer relationship?",
            "weight": 2.0,
            "keywords": ["direct_sales", "customer_list", "subscriber", "community", "audience", "brand_loyalty"]
        },
        "information_advantage": {
            "description": "Do you know something others don't?",
            "weight": 2.0,
            "keywords": ["proprietary_data", "market_intelligence", "pricing_data", "deal_flow", "sourcing_contacts"]
        },
        "switching_cost_created": {
            "description": "How hard is it to replace you?",
            "weight": 1.5,
            "keywords": ["integration", "custom", "trained", "certified", "embedded", "api_dependency", "workflow"]
        },
        "replaceability": {
            "description": "How easily can someone else do this? (inverted — high = hard to replace)",
            "weight": 1.5,
            "keywords": ["unique", "patent", "exclusive", "licensed", "specialized", "rare_skill", "monopoly"]
        },
        "risk_bearing": {
            "description": "Are you bearing risk others won't?",
            "weight": 1.0,
            "keywords": ["guarantee", "warranty", "insurance", "inventory_risk", "credit_risk", "escrow"]
        },
        "trust_position": {
            "description": "Are you the trust anchor in the chain?",
            "weight": 2.0,
            "keywords": ["verified", "trusted", "reputation", "track_record", "references", "certified", "audited"]
        }
    }

    EXIT_QUESTIONS = [
        {"id": "E1", "question": "Who specifically would buy this business?", "good_answer_signals": ["named_buyer_type", "competitor", "pe_firm", "strategic_acquirer"]},
        {"id": "E2", "question": "What are they actually buying? (asset, not revenue)", "good_answer_signals": ["customer_list", "data", "brand", "technology", "relationships", "licenses"]},
        {"id": "E3", "question": "What multiple is realistic? (cite comparable exits)", "good_answer_signals": ["specific_multiple", "comparable_cited", "industry_benchmark"]},
        {"id": "E4", "question": "Can you sell to multiple buyers simultaneously?", "good_answer_signals": ["yes_competitive_auction", "strategic_vs_financial", "multiple_interested"]},
        {"id": "E5", "question": "What's the minimum timeline to exit-readiness?", "good_answer_signals": ["under_3_years", "clear_milestones", "defined_metrics"]}
    ]

    VALUE_CHAIN_ROLES = {
        "producer": {"keywords": ["manufacture", "create", "build", "develop", "grow", "mine"], "typical_margin": "10-30%"},
        "aggregator": {"keywords": ["collect", "aggregate", "bundle", "curate", "source", "procure"], "typical_margin": "15-25%"},
        "distributor": {"keywords": ["distribute", "ship", "deliver", "logistics", "wholesale", "channel"], "typical_margin": "5-15%"},
        "platform": {"keywords": ["marketplace", "platform", "network", "exchange", "connect", "match"], "typical_margin": "15-40%"},
        "financier": {"keywords": ["fund", "lend", "invest", "insure", "underwrite", "finance"], "typical_margin": "20-50%"}
    }

    @classmethod
    def calculate_position_score(cls, dimensions: Dict[str, int]) -> Dict:
        """Calculate weighted position score from dimension ratings (0-10 each)."""
        if not dimensions:
            return {"score": 1, "interpretation": "unscored", "dimensions": {}}

        total_weight = 0
        weighted_sum = 0
        detail = {}

        for dim_name, config in cls.POSITION_DIMENSIONS.items():
            raw = min(max(dimensions.get(dim_name, 0), 0), 10)
            w = config["weight"]
            weighted_sum += raw * w
            total_weight += w
            detail[dim_name] = {"raw": raw, "weight": w, "weighted": round(raw * w, 2)}

        score = round(weighted_sum / max(total_weight, 1), 1)

        if score >= 7:
            interp = "dominant_position"
        elif score >= 5:
            interp = "strong_position"
        elif score >= 3:
            interp = "moderate_position"
        else:
            interp = "weak_position"

        return {"score": score, "interpretation": interp, "dimensions": detail}

    @classmethod
    def evaluate_exit_design(cls, answers: Dict) -> Dict:
        """Evaluate exit readiness from answers to 5 exit questions."""
        results = []
        score = 0

        for q in cls.EXIT_QUESTIONS:
            answer = answers.get(q["id"], "")
            answer_lower = answer.lower() if answer else ""
            signals_hit = [s for s in q["good_answer_signals"] if s in answer_lower]
            q_score = min(len(signals_hit) * 3.3, 10)
            has_substance = len(answer) > 20
            if has_substance:
                q_score = max(q_score, 4)
            score += q_score
            results.append({
                "question_id": q["id"],
                "question": q["question"],
                "answer_provided": bool(answer),
                "signals_matched": signals_hit,
                "score": round(q_score, 1)
            })

        avg = round(score / max(len(cls.EXIT_QUESTIONS), 1), 1)

        if avg >= 7:
            readiness = "high"
        elif avg >= 4:
            readiness = "medium"
        elif avg > 0:
            readiness = "low"
        else:
            readiness = "not_designed"

        gaps = [r["question"] for r in results if r["score"] < 4]

        return {"exit_score": avg, "readiness": readiness, "question_results": results, "gaps": gaps}

    @classmethod
    def classify_value_chain_role(cls, description: str) -> Dict:
        """Classify where in value chain this business sits."""
        desc_lower = description.lower()
        scores = {}

        for role, config in cls.VALUE_CHAIN_ROLES.items():
            hits = sum(1 for kw in config["keywords"] if kw in desc_lower)
            if hits:
                scores[role] = hits

        if not scores:
            return {"primary_role": "unknown", "confidence": 0, "typical_margin": "varies"}

        primary = max(scores, key=scores.get)
        confidence = min(scores[primary] / 3.0, 1.0)

        return {
            "primary_role": primary,
            "confidence": round(confidence, 2),
            "typical_margin": cls.VALUE_CHAIN_ROLES[primary]["typical_margin"],
            "all_roles": {k: v for k, v in sorted(scores.items(), key=lambda x: x[1], reverse=True)}
        }

    @classmethod
    def auto_score_dimensions(cls, description: str) -> Dict[str, int]:
        """Auto-score dimensions from description keywords (deterministic proxy)."""
        desc_lower = description.lower()
        dims = {}
        for dim_name, config in cls.POSITION_DIMENSIONS.items():
            hits = sum(1 for kw in config["keywords"] if kw in desc_lower)
            dims[dim_name] = min(hits * 3, 10)
        return dims

    @classmethod
    def full_analysis(cls, description: str, exit_answers: Optional[Dict] = None) -> Dict:
        """Complete position intelligence analysis."""
        dims = cls.auto_score_dimensions(description)
        pos_score = cls.calculate_position_score(dims)
        role = cls.classify_value_chain_role(description)

        result = {
            "position_score": pos_score,
            "value_chain_role": role,
            "exit_design": None
        }

        if exit_answers:
            result["exit_design"] = cls.evaluate_exit_design(exit_answers)

        return result


def main():
    parser = argparse.ArgumentParser(description="Position Intelligence Analyzer")
    parser.add_argument("--description", type=str, required=True, help="Business description")
    parser.add_argument("--exit-answers", type=str, default=None, help="JSON dict of exit question answers")
    parser.add_argument("--output", choices=["json", "text"], default="json")
    args = parser.parse_args()

    exit_ans = json.loads(args.exit_answers) if args.exit_answers else None
    result = PositionIntelligence.full_analysis(args.description, exit_ans)

    if args.output == "json":
        print(json.dumps(result, indent=2))
    else:
        ps = result["position_score"]
        print(f"Position Score: {ps['score']}/10 ({ps['interpretation']})")
        print(f"Value Chain Role: {result['value_chain_role']['primary_role']}")
        if result["exit_design"]:
            ed = result["exit_design"]
            print(f"Exit Readiness: {ed['readiness']} ({ed['exit_score']}/10)")
            if ed["gaps"]:
                print(f"Exit Gaps: {len(ed['gaps'])} unanswered questions")
    return 0


if __name__ == "__main__":
    sys.exit(main())

