def load_recent_log_entries(days: int) -> list[dict[str, Any]]:
    if not EVOLUTION_LOG.exists():
        return []
    cutoff = datetime.now(timezone.utc) - timedelta(days=days)
    out = []
    with open(EVOLUTION_LOG, "r", encoding="utf-8") as f:
        for line in f:
            try:
                rec = json.loads(line)
                ts = datetime.fromisoformat(rec.get("ts", "").replace("Z", "+00:00"))
                if ts >= cutoff:
                    out.append(rec)
            except Exception:
                continue
    return out


def compute_metrics() -> dict[str, Any]:
    """Aggregate metrics from calibration + drift logs."""
    metrics: dict[str, Any] = {
        "brier_avg_30d": None,
        "drift_alerts_count_7d": 0,
        "silent_persistence_failures_count": 0,
        "kb_query_false_positive_rate": None,
        "orphaned_outcomes_30d": 0,
    }

    try:
        result = subprocess.run(
            [str(PYTHON), str(UPDATE_CALIBRATION), "stats"],
            capture_output=True, encoding="utf-8", errors="replace", timeout=10,
        )
        if result.returncode == 0:
            stats = json.loads(result.stdout)
            metrics["brier_avg_30d"] = stats.get("brier_avg_30d")
            metrics["orphaned_outcomes_30d"] = stats.get("orphaned_count", 0)
    except Exception as e:
        print(f"  WARN: stats fetch failed: {e}", file=sys.stderr)

    if DRIFT_ALERTS.exists():
        cutoff = datetime.now(timezone.utc) - timedelta(days=7)
        with open(DRIFT_ALERTS, "r", encoding="utf-8") as f:
            for line in f:
                try:
                    rec = json.loads(line)
                    ts = datetime.fromisoformat(rec.get("ts", "").replace("Z", "+00:00"))
                    if ts >= cutoff:
                        metrics["drift_alerts_count_7d"] += 1
                except Exception:
                    continue

    return metrics


def evaluate_trigger(trigger: dict[str, Any], metrics: dict[str, Any]) -> bool:
    metric_name = trigger.get("metric")
    threshold = trigger.get("threshold")
    op = trigger.get("operator", ">")
    actual = metrics.get(metric_name)
    if actual is None:
        return False
    try:
        actual = float(actual)
        threshold = float(threshold)
    except (TypeError, ValueError):
        return False
    if op == ">":
        return actual > threshold
    if op == ">=":
        return actual >= threshold
    if op == "<":
        return actual < threshold
    if op == "<=":
        return actual <= threshold
    if op == "==":
        return actual == threshold
    return False


def check_rate_limit(rate_limits: dict[str, Any]) -> bool:
    """Returns True if we are within rate limit (allowed to fire)."""
    max_per_24h = int(rate_limits.get("max_user_surfaced_events_per_24h", 1))
    recent = load_recent_log_entries(days=1)
    surfaced = [r for r in recent if r.get("user_surfaced")]
    return len(surfaced) < max_per_24h


