#!/usr/bin/env python3
"""
Value chain position scorer and exit-first design evaluator.

6 position dimensions:
1. Control over demand (do you own the customer relationship?)
2. Information advantage (do you know something others don't?)
3. Switching cost created (how hard to replace you?)
4. Replaceability (inverted — how easily can someone else do this?)
5. Risk bearing (are you bearing risk others won't?)
6. Trust position (are you the trust anchor in the chain?)

Usage:
    python -m money_mechanisms.position_intelligence --description "B2B marketplace connecting VN manufacturers with US buyers"
"""

import argparse
import json
import re
import sys
from typing import Dict, List, Optional


class PositionIntelligence:
    """Value chain position scorer and exit-first designer."""

    POSITION_DIMENSIONS = {
        "control_over_demand": {
            "description": "Do you own the customer relationship?",
            "weight": 2.0,
            "keywords": ["direct_sales", "customer_list", "subscriber", "community", "audience", "brand_loyalty"]
        },
        "information_advantage": {
            "description": "Do you know something others don't?",
            "weight": 2.0,
            "keywords": ["proprietary_data", "market_intelligence", "pricing_data", "deal_flow", "sourcing_contacts"]
        },
        "switching_cost_created": {
            "description": "How hard is it to replace you?",
            "weight": 1.5,
            "keywords": ["integration", "custom", "trained", "certified", "embedded", "api_dependency", "workflow"]
        },
        "replaceability": {
            "description": "How easily can someone else do this? (inverted — high = hard to replace)",
            "weight": 1.5,
            "keywords": ["unique", "patent", "exclusive", "licensed", "specialized", "rare_skill", "monopoly"]
        },
        "risk_bearing": {
            "description": "Are you bearing risk others won't?",
            "weight": 1.0,
            "keywords": ["guarantee", "warranty", "insurance", "inventory_risk", "credit_risk", "escrow"]
        },
        "trust_position": {
            "description": "Are you the trust anchor in the chain?",
            "weight": 2.0,
            "keywords": ["verified", "trusted", "reputation", "track_record", "references", "certified", "audited"]
        }
    }

    EXIT_QUESTIONS = [
        {"id": "E1", "question": "Who specifically would buy this business?", "good_answer_signals": ["named_buyer_type", "competitor", "pe_firm", "strategic_acquirer"]},
        {"id": "E2", "question": "What are they actually buying? (asset, not revenue)", "good_answer_signals": ["customer_list", "data", "brand", "technology", "relationships", "licenses"]},
        {"id": "E3", "question": "What multiple is realistic? (cite comparable exits)", "good_answer_signals": ["specific_multiple", "comparable_cited", "industry_benchmark"]},
        {"id": "E4", "question": "Can you sell to multiple buyers simultaneously?", "good_answer_signals": ["yes_competitive_auction", "strategic_vs_financial", "multiple_interested"]},
        {"id": "E5", "question": "What's the minimum timeline to exit-readiness?", "good_answer_signals": ["under_3_years", "clear_milestones", "defined_metrics"]}
    ]

    VALUE_CHAIN_ROLES = {
        "producer": {"keywords": ["manufacture", "create", "build", "develop", "grow", "mine"], "typical_margin": "10-30%"},
        "aggregator": {"keywords": ["collect", "aggregate", "bundle", "curate", "source", "procure"], "typical_margin": "15-25%"},
        "distributor": {"keywords": ["distribute", "ship", "deliver", "logistics", "wholesale", "channel"], "typical_margin": "5-15%"},
        "platform": {"keywords": ["marketplace", "platform", "network", "exchange", "connect", "match"], "typical_margin": "15-40%"},
        "financier": {"keywords": ["fund", "lend", "invest", "insure", "underwrite", "finance"], "typical_margin": "20-50%"}
    }

    @classmethod
    def calculate_position_score(cls, dimensions: Dict[str, int]) -> Dict:
        """Calculate weighted position score from dimension ratings (0-10 each)."""
        if not dimensions:
            return {"score": 1, "interpretation": "unscored", "dimensions": {}}

        total_weight = 0
        weighted_sum = 0
        detail = {}

        for dim_name, config in cls.POSITION_DIMENSIONS.items():
            raw = min(max(dimensions.get(dim_name, 0), 0), 10)
            w = config["weight"]
            weighted_sum += raw * w
            total_weight += w
            detail[dim_name] = {"raw": raw, "weight": w, "weighted": round(raw * w, 2)}

        score = round(weighted_sum / max(total_weight, 1), 1)

        if score >= 7:
            interp = "dominant_position"
        elif score >= 5:
            interp = "strong_position"
        elif score >= 3:
            interp = "moderate_position"
        else:
            interp = "weak_position"

        return {"score": score, "interpretation": interp, "dimensions": detail}

    @classmethod
    def evaluate_exit_design(cls, answers: Dict) -> Dict:
        """Evaluate exit readiness from answers to 5 exit questions."""
        results = []
        score = 0

        for q in cls.EXIT_QUESTIONS:
            answer = answers.get(q["id"], "")
            answer_lower = answer.lower() if answer else ""
            signals_hit = [s for s in q["good_answer_signals"] if s in answer_lower]
            q_score = min(len(signals_hit) * 3.3, 10)
            has_substance = len(answer) > 20
            if has_substance:
                q_score = max(q_score, 4)
            score += q_score
            results.append({
                "question_id": q["id"],
                "question": q["question"],
                "answer_provided": bool(answer),
                "signals_matched": signals_hit,
                "score": round(q_score, 1)
            })

        avg = round(score / max(len(cls.EXIT_QUESTIONS), 1), 1)

        if avg >= 7:
            readiness = "high"
        elif avg >= 4:
            readiness = "medium"
        elif avg > 0:
            readiness = "low"
        else:
            readiness = "not_designed"

        gaps = [r["question"] for r in results if r["score"] < 4]

        return {"exit_score": avg, "readiness": readiness, "question_results": results, "gaps": gaps}

    @classmethod
    def classify_value_chain_role(cls, description: str) -> Dict:
        """Classify where in value chain this business sits."""
        desc_lower = description.lower().replace("-", "_").replace(" ", "_")
        scores = {}

        for role, config in cls.VALUE_CHAIN_ROLES.items():
            hits = sum(1 for kw in config["keywords"] if kw in desc_lower)
            if hits:
                scores[role] = hits

        if not scores:
            return {"primary_role": "unknown", "confidence": 0, "typical_margin": "varies"}

        primary = max(scores, key=scores.get)
        confidence = min(scores[primary] / 3.0, 1.0)

        return {
            "primary_role": primary,
            "confidence": round(confidence, 2),
            "typical_margin": cls.VALUE_CHAIN_ROLES[primary]["typical_margin"],
            "all_roles": {k: v for k, v in sorted(scores.items(), key=lambda x: x[1], reverse=True)}
        }

    @classmethod
    def auto_score_dimensions(cls, description: str) -> Dict[str, int]:
        """Auto-score dimensions from description keywords (deterministic proxy)."""
        desc_lower = description.lower()
        dims = {}
        for dim_name, config in cls.POSITION_DIMENSIONS.items():
            hits = sum(1 for kw in config["keywords"] if kw in desc_lower)
            dims[dim_name] = min(hits * 3, 10)
        return dims

    @classmethod
    def full_analysis(cls, description: str, exit_answers: Optional[Dict] = None) -> Dict:
        """Complete position intelligence analysis."""
        dims = cls.auto_score_dimensions(description)
        pos_score = cls.calculate_position_score(dims)
        role = cls.classify_value_chain_role(description)

        result = {
            "position_score": pos_score,
            "value_chain_role": role,
            "exit_design": None
        }

        if exit_answers:
            result["exit_design"] = cls.evaluate_exit_design(exit_answers)

        return result


def main():
    parser = argparse.ArgumentParser(description="Position Intelligence Analyzer")
    parser.add_argument("--description", type=str, required=True, help="Business description")
    parser.add_argument("--exit-answers", type=str, default=None, help="JSON dict of exit question answers")
    parser.add_argument("--output", choices=["json", "text"], default="json")
    args = parser.parse_args()

    exit_ans = json.loads(args.exit_answers) if args.exit_answers else None
    result = PositionIntelligence.full_analysis(args.description, exit_ans)

    if args.output == "json":
        print(json.dumps(result, indent=2))
    else:
        ps = result["position_score"]
        print(f"Position Score: {ps['score']}/10 ({ps['interpretation']})")
        print(f"Value Chain Role: {result['value_chain_role']['primary_role']}")
        if result["exit_design"]:
            ed = result["exit_design"]
            print(f"Exit Readiness: {ed['readiness']} ({ed['exit_score']}/10)")
            if ed["gaps"]:
                print(f"Exit Gaps: {len(ed['gaps'])} unanswered questions")
    return 0


if __name__ == "__main__":
    sys.exit(main())

