def _load_structural_knobs(self) -> Dict[str, float]:
    """Load structural weights from mechanism-knobs.json, fallback to defaults."""
    defaults = {"structural_leverage_weight": 1.0, "exit_score_weight": 1.0, "topology_bonus_weight": 0.5}
    try:
        knobs_path = Path(__file__).parent.parent.parent.parent.parent / "data" / "config" / "mechanism-knobs.json"
        if knobs_path.exists():
            data = json.loads(knobs_path.read_text(encoding="utf-8"))
            knobs = data.get("knobs", {})
            return {k: knobs.get(k, {}).get("value", v) for k, v in defaults.items()}
    except Exception:
        pass
    return defaults

def _analyze_structure(self, query: str, context: Dict) -> Optional[Dict]:
    """Analyze structural leverage patterns (Layer A+B+C). Advisory only."""
    if not HAS_STRUCTURAL:
        return None

    multi_entity_kw = [
        "franchise", "holding", "subsidiary", "spv", "marketplace", "platform",
        "escrow", "float", "licensing", "multi_entity", "broker", "intermediary",
        "white_label", "prepaid", "deposit"
    ]
    query_lower = query.lower()
    if not any(kw in query_lower for kw in multi_entity_kw):
        return {"structure_score": 1, "detail": "linear_single_entity", "skipped": True}

    topology = FlowTopologyAnalyzer.full_analysis(query)
    structural = StructuralLeverageScorer.full_analysis(query)
    position = PositionIntelligence.full_analysis(query)

    knobs = self._load_structural_knobs()
    topo_weight = knobs["topology_bonus_weight"]
    struct_weight = knobs["structural_leverage_weight"]
    exit_weight = knobs["exit_score_weight"]
    total_weight = topo_weight + struct_weight + exit_weight

    topo_score = topology["topology_score"]["score"]
    struct_score = structural["structural_score"]["score"]
    pos_score = position["position_score"]["score"]
    composite = round((topo_score * topo_weight + struct_score * struct_weight + pos_score * exit_weight) / max(total_weight, 1) * 10 / 10, 1)

